('23db79cb-a69f-45d0-aeda-097a1e101c54', '21feff02-016d-46e2-bb9d-c27495133b1b', '98. óra: Hosszúság, tömeg, idő', 'A hosszúság, tömeg és idő mérésének ismétlése, mértékegységek és átváltások.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "f461b896-7e68-499b-b1e9-25c92f59377b", "text": "Hány milliméter 1 méter?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "26f8e5ef-4797-4859-a8c3-3a9bc19d6ac6", "text": "Hány dekagramm (dkg) 1 kilogramm (kg)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "90b7c390-ec9f-4d7a-9573-b174d365a340", "text": "Hány másodperc van 1 órában? (60 * 60)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3600"}, {"id": "8efe9eb2-c4bc-42a8-a865-f47250ac010d", "text": "Mennyi 2,5 km méterben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}, {"id": "9a86e554-fae9-46c8-ab66-2057f874ecf4", "text": "Hány kilogramm 3,5 tonna?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3500"}, {"id": "dec28a41-f167-4b57-8a33-d6ea281d1c8f", "text": "Az időváltás 60-as alapon működik a másodperc, perc és óra között.", "type": "true-false", "options": [{"id": "90cd2251-2155-45dc-a4c7-a7c0567f028c", "text": "Igaz", "isCorrect": true}, {"id": "9d03184b-b6b1-4dc2-9a4c-94a445863747", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "62eec457-fe9e-475a-9e72-d26aa5ff6f1a", "text": "Hány perc 2 óra 15 perc?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "135"}]'::jsonb, true, NOW()),
('aa04773d-72b8-4031-8250-fdc3f5ec361f', '21feff02-016d-46e2-bb9d-c27495133b1b', '99. óra: Hosszúság, tömeg, idő II.', 'Összetett mértékegység-átváltási feladatok és gyakorlás.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "f536b8a4-10ec-43d8-9253-8da68ccb35ca", "text": "Hány cm van 4,5 m-ben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "450"}, {"id": "07b83170-832a-495a-ad5f-e99d04e2b073", "text": "Hány gramm 0,75 kg?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "750"}, {"id": "253ab087-2979-492e-aead-900c2b193e2c", "text": "Hány napból áll 4 hét?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "f6d106d0-e0ca-4899-8c00-e3214edccda2", "text": "A 1500 m megegyezik 1,5 km-rel.", "type": "true-false", "options": [{"id": "8ab6de9e-e3b9-4461-b353-9efa88967d74", "text": "Igaz", "isCorrect": true}, {"id": "398e9c61-0ce4-475a-bd36-8a18a37c011a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ff258cd3-ac0d-475d-b83b-a8b2ac9cb802", "text": "Mennyi 500 dkg kg-ban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "e1249acd-0377-4d4b-9c62-7b7fc92dd98a", "text": "Hány perc 1 nap negyede (6 óra)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "5671093c-720d-4c0e-a50e-a88584d7f458", "text": "A nagyobb mértékegységből kisebb felé haladva szorzunk a váltószámmal.", "type": "true-false", "options": [{"id": "0bf9841b-d54f-4dd4-a8da-bc5ab07aa681", "text": "Igaz", "isCorrect": true}, {"id": "e8737a9b-3db0-4911-b1d6-7c4270ccaeb1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('37490e6f-74c0-4a38-832b-e04f5f89dae9', '21feff02-016d-46e2-bb9d-c27495133b1b', '100. óra: A sokszögek kerülete', 'Négyzet, téglalap, háromszög és sokszögek kerületének számítása (K).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "6b26d685-794d-4af5-b006-40b48d3c1b95", "text": "Mi a téglalap kerületének képlete (a és b oldallal)?", "type": "multiple-choice", "options": [{"id": "49460631-2307-4eb2-9572-e242ffcc1717", "text": "K = 2 * (a + b)", "isCorrect": true}, {"id": "6ba28773-2482-4099-8812-2312bfcf8939", "text": "K = a * b", "isCorrect": false}, {"id": "430a65b9-0bb0-4551-b905-9e3a4e3be1c1", "text": "K = a + b", "isCorrect": false}, {"id": "98d74204-52f3-4076-927e-016b3dc30f08", "text": "K = 4 * a", "isCorrect": false}], "timeLimit": 15}, {"id": "f80d8b57-1a8d-4ac2-bd06-e7ed23c7c9d8", "text": "Mi a négyzet kerületének képlete (''a'' oldallal)?", "type": "multiple-choice", "options": [{"id": "569157e6-aecc-45fa-90cd-124eae28ad8d", "text": "K = 4 * a", "isCorrect": true}, {"id": "52acfa3b-2764-4237-be7a-6537a6477a0f", "text": "K = a * a", "isCorrect": false}, {"id": "04bcdc92-6d05-4f71-9feb-c0ed1d5d6801", "text": "K = 2 * a", "isCorrect": false}, {"id": "ee81f6ec-6bea-4438-ba99-af15a23b92a7", "text": "K = 6 * a", "isCorrect": false}], "timeLimit": 15}, {"id": "225cf31d-3b57-40d6-8ebc-94eba42765e8", "text": "Mennyi a 6 cm és 8 cm oldalú téglalap kerülete? (2 * (6 + 8))", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "cc3f7ce0-ec17-4d37-a5e5-7834cf385983", "text": "Mennyi a 7 cm oldalú négyzet kerülete? (4 * 7)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "3fd2a9c0-ac32-4344-a1cd-bc8721750057", "text": "Mennyi a 3 cm, 4 cm, 5 cm oldalú háromszög kerülete? (3+4+5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "47a700a6-3dcc-4ddd-afcf-f2b2c2c4bb00", "text": "A kerület a sokszöget határoló oldalak hosszának összege.", "type": "true-false", "options": [{"id": "bbd7a34a-d3d2-48ba-99c1-fcf3f31c3514", "text": "Igaz", "isCorrect": true}, {"id": "0ddbec3f-376f-4e41-946b-a756ee275f3b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "62069e97-0846-4bc6-9326-235ed526b5ba", "text": "Mennyi a 5 cm oldalú szabályos ötszög kerülete? (5 * 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}]'::jsonb, true, NOW()),
('d9f22feb-fcbc-4e2e-98b4-9eccec23a2e7', '21feff02-016d-46e2-bb9d-c27495133b1b', '101. óra: Feladatmegoldás', 'Összetett kerületszámítási és kerítésszámítási szöveges feladatok.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "91607c2d-93f9-4a99-a114-a57d5a1c1415", "text": "Egy téglalap alakú kert hossza 20 m, szélessége 15 m. Hány méter kerítés övezi a kertet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "70"}, {"id": "bbffdc6f-1ee3-4ea0-a5e4-a70d2d47133e", "text": "Hány méter kerítés kell a 20m x 15m-es kerthez, ha hagyunk egy 2 m-es kaput? (70 - 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "68"}, {"id": "2d0899c7-12e8-481b-938c-c738d836fa6c", "text": "Egy négyzet alakú pálya kerülete 100 m. Hány méter hosszú a pálya egy oldala? (100 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "5d933d01-f3a0-407d-9584-dd417b70091c", "text": "Ha a téglalap kerülete 30 cm, és egyik oldala 5 cm, mekkora a másik oldal? (15 - 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "d65b0ba6-9546-4995-8b8f-ecce383976f0", "text": "A sokszögek kerületét mindig hosszúság-mértékegységben (m, cm, mm) adjuk meg.", "type": "true-false", "options": [{"id": "064fcfd7-9e1c-4105-9dfd-961ad6f6a4cc", "text": "Igaz", "isCorrect": true}, {"id": "2837d9a5-62f7-47e5-957b-41138c44861b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "36108a29-b08f-432b-b1c3-caff89193090", "text": "Mennyi a 10 cm oldalú szabályos hatszög kerülete?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "2224529e-22de-4dda-b052-06400666ad25", "text": "A kerületszámításos feladatoknál az oldalaknak azonos mértékegységben kell lenniük.", "type": "true-false", "options": [{"id": "8a60c036-70dd-4480-9277-6dc48e6235ef", "text": "Igaz", "isCorrect": true}, {"id": "f29d6e1c-929b-4aee-8d6c-500e28140c8c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('3b104664-7d79-485d-a69b-360087c5ec2e', '21feff02-016d-46e2-bb9d-c27495133b1b', '102. óra: A terület és a térfogat mérése', 'A terület és térfogat mértékegységei, lefedés, egységkockák, átváltások.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "424dc05c-fb35-4750-9e0f-05e2c86a999b", "text": "Mi a terület alapvető mértékegysége az SI-ben?", "type": "multiple-choice", "options": [{"id": "ff6f2735-eaea-47fc-852b-2996ce0a4f12", "text": "Négyzetméter (m²)", "isCorrect": true}, {"id": "a13c83aa-1cd4-4a67-8202-e5e23c46ee07", "text": "Méter (m)", "isCorrect": false}, {"id": "c986955e-33d6-49dc-922c-b1b28d73a63f", "text": "Köbméter (m³)", "isCorrect": false}, {"id": "43258a90-990c-49a7-a969-a3791537d360", "text": "Liter (l)", "isCorrect": false}], "timeLimit": 15}, {"id": "a31bf707-9ed8-4a31-ac4c-d8721bfd10cd", "text": "Hány cm² 1 dm²? (10 * 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "53d22c34-c5f4-4618-928f-cb3d738d4ee7", "text": "Hány dm² 1 m²? (10 * 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "01d9026e-f914-4e00-b551-0396640941a6", "text": "Hány dm³ 1 m³? (10 * 10 * 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "16c5615d-fb64-4320-99fc-0828b1720144", "text": "1 liter űrtartalom pontosan 1 köbdeciméternek (1 dm³) felel meg.", "type": "true-false", "options": [{"id": "98435ffd-8ec4-4626-a211-4bb24581ba5b", "text": "Igaz", "isCorrect": true}, {"id": "eb07724b-a6ea-44c1-a256-9eba73912eda", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b0caa409-1ff9-4bc3-89fb-1522accca011", "text": "Hány cm³ 1 dm³?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "85a859e1-8810-4711-8ec8-afc9101601fc", "text": "A terület mértékegységei között a szomszédos váltószám 100 (területnél 10²).", "type": "true-false", "options": [{"id": "3576dbff-f025-4da8-b409-a95a29007c5f", "text": "Igaz", "isCorrect": true}, {"id": "e5b75e1c-5f5f-46d8-868a-314e5067c9a3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('10ffff7b-5f8c-4a75-a147-d06e9d365849', '21feff02-016d-46e2-bb9d-c27495133b1b', '103. óra: Gyakorlóóra. A terület és a térfogat mérése', 'Terület- és térfogat-mértékegységek gyakorlása digitális feladatlapokon.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "c86061b7-6a19-4b25-ac0d-4c10d0af5928", "text": "Hány mm² 1 cm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "6b65adda-21f5-413f-b652-7105f451b801", "text": "Hány cm³ 2 liter? (2 dm³ = 2000 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "7a454d84-9efb-4e48-80a5-06015382ad77", "text": "Hány m² 500 dm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "a6538219-56e4-4f36-b5c6-091a8166a74d", "text": "Hány litere felel meg 3,5 dm³ víznek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3.5"}, {"id": "511e9199-1138-47ff-8480-9e31b771b091", "text": "A térfogat mértékegységei között a szomszédos váltószám 1000 (10³).", "type": "true-false", "options": [{"id": "5502f109-6856-4714-b410-e6c05b1bae38", "text": "Igaz", "isCorrect": true}, {"id": "961378e3-122c-45db-9d08-767545f2b139", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "26cb8ce4-713a-49d7-84fe-f9a2b97b83b2", "text": "Hány dl 1 liter?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "15f6af5e-15ed-4867-b444-1b7de1877359", "text": "Hány ml 1 dm³ (1 liter)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW()),
('4d2b983a-d5c2-40a4-8391-efe2c04ed733', '21feff02-016d-46e2-bb9d-c27495133b1b', '104. óra: A sokszögek területe', 'Négyzet, téglalap és derékszögű háromszög területe (T).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "732dcacc-125b-4d61-857d-d3260b7e74ad", "text": "Mi a téglalap területének képlete (a és b oldallal)?", "type": "multiple-choice", "options": [{"id": "242e6904-0fb7-412f-8603-90e76587642d", "text": "T = a * b", "isCorrect": true}, {"id": "06b41fc8-424b-4ad6-b0fe-5f268478217c", "text": "T = 2 * (a + b)", "isCorrect": false}, {"id": "e0986867-0667-46b5-952b-a712eb4f86b7", "text": "T = a + b", "isCorrect": false}, {"id": "b1959e54-f160-446b-8454-22046adb5e2c", "text": "T = a * a * a", "isCorrect": false}], "timeLimit": 15}, {"id": "cf4bdefe-094d-420f-a32a-ae5eab41393b", "text": "Mi a négyzet területének képlete (''a'' oldallal)?", "type": "multiple-choice", "options": [{"id": "06c87d80-0358-47a3-93a1-5c5b2b4c4590", "text": "T = a * a (a²)", "isCorrect": true}, {"id": "61e58c17-2c18-481b-b67d-cec7226494b6", "text": "T = 4 * a", "isCorrect": false}, {"id": "8de6bbda-bec1-4be1-b08b-21c7734fa73c", "text": "T = 2 * a", "isCorrect": false}, {"id": "f09471a8-3909-4f7b-a9dc-f0e33a177aa3", "text": "T = a * 10", "isCorrect": false}], "timeLimit": 15}, {"id": "66b36c63-298a-4df5-ab99-1ce1645c48b4", "text": "Mennyi a 6 cm és 8 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "48"}, {"id": "458235f7-abc4-43e0-ae31-f7779896d9d9", "text": "Mennyi a 5 cm oldalú négyzet területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "5a8dbe9b-7e28-4757-a2b7-f11b1901e7af", "text": "Mi a derékszögű háromszög területének képlete (a és b befogókkal)?", "type": "multiple-choice", "options": [{"id": "216715f5-c936-4e51-b8ee-b4de699eded3", "text": "T = (a * b) / 2", "isCorrect": true}, {"id": "b8c55cff-f22c-4685-b784-fa70a07de1ab", "text": "T = a * b", "isCorrect": false}, {"id": "03e543f3-8294-4ec7-a9aa-7e4f76e14b1e", "text": "T = a + b", "isCorrect": false}, {"id": "f39d30d8-a664-4be6-82c7-299b3768408f", "text": "T = 2 * a * b", "isCorrect": false}], "timeLimit": 15}, {"id": "24ef35cd-ccf0-47ee-ba35-a3c78578c784", "text": "Mennyi a 6 cm és 8 cm befogójú derékszögű háromszög területe? ((6*8)/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "7fb978a8-706b-40d5-b1e3-e90551e4f1ed", "text": "A derékszögű háromszög területe a két befogójú téglalap területének fele.", "type": "true-false", "options": [{"id": "a89efd26-4b4f-48f8-aa55-f74954f0d1d5", "text": "Igaz", "isCorrect": true}, {"id": "fe4144ef-0efc-481a-8e18-ea076821fc5e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('77da2fc2-00b2-482a-8b91-67eb7b1771fd', '21feff02-016d-46e2-bb9d-c27495133b1b', '105. óra: Feladatmegoldás', 'Kerület- és területszámítási feladatok, lakóház és szobapadló tervezése.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "3db4885b-c927-4ec2-a5c3-40a2d65347a8", "text": "Egy 5 m hosszú és 4 m széles szobába szőnyeget fektetünk. Hány m² a szoba területe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "a13beabd-480f-4da9-930a-e324f56a2b47", "text": "Ha a parketta ára 5000 Ft/m², mennyibe kerül a 20 m²-es szoba parkettázása?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100000"}, {"id": "8f370acb-ddda-446c-b798-58f8f54ed32a", "text": "Hány méter szegélylécre van szükség a 5m x 4m-es szobához (kerület)? (2*(5+4))", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "ea920a65-e8c1-451a-92dc-8ce235187576", "text": "Egy négyzet alakú szoba területe 36 m². Hány méter hosszú a szoba egy oldala?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "95ce539f-c005-4565-bb84-fbcfe129f0f0", "text": "A terület számításához a méreteket azonos mértékegységre kell hozni a szorzás előtt.", "type": "true-false", "options": [{"id": "c9f8ac84-05b2-41cf-a147-9d047c59b9c2", "text": "Igaz", "isCorrect": true}, {"id": "63577b9e-5d2c-47b6-8507-bf9300835d73", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "88e56f5c-dd65-4824-9d42-7aa5e9cc047b", "text": "Mennyi a 10 cm és 4 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "086c84e9-8091-4037-bd53-5e9ff4419310", "text": "A lakástervezésben a m² alapvető fontosságú.", "type": "true-false", "options": [{"id": "6b74178a-2bee-436f-9f06-aeb04f50e5bc", "text": "Igaz", "isCorrect": true}, {"id": "08ea4246-8133-4924-9752-424c534fb415", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('ef36e54a-581a-4fb8-97f1-e3e6b35a183a', '21feff02-016d-46e2-bb9d-c27495133b1b', '106. óra: Alakzatok a térben', 'Testek elnevezései (kocka, téglatest, hasáb, piramis), él, lap, csúcs, nézetek (elölnézet, felülnézet, oldalnézet).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "23775e90-f47f-40c7-81b4-9fe5dc0844a3", "text": "Hány lapja van a téglatestnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "0ab3d296-9bf4-47e2-b543-4bab3c5958a0", "text": "Hány csúcsa van a téglatestnek (és a kockának)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "0f01e3b9-0e9c-4502-9ed6-de09c32f9622", "text": "Hány éle van a téglatestnek (és a kockának)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "d8d9b7f4-ec45-42bb-8247-244da3fe1b39", "text": "A kocka minden lapja egyenlő négyzet.", "type": "true-false", "options": [{"id": "e56af868-e641-439b-b496-9fe977e827c9", "text": "Igaz", "isCorrect": true}, {"id": "b0a8c306-65f1-44c2-a432-d5ad8ccbeda0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d48ef006-57fb-4133-9250-73ae12b23ceb", "text": "Milyen alakúak a téglatest lapjai?", "type": "multiple-choice", "options": [{"id": "83684d01-a673-4edd-8ffa-6b576ceb170c", "text": "Téglalapok (melyek között négyzet is lehet)", "isCorrect": true}, {"id": "3a093dfc-c8d3-43d3-9488-78032d54a06b", "text": "Háromszögek", "isCorrect": false}, {"id": "c3655c28-0777-4f16-b8af-37366a5c5d40", "text": "Körök", "isCorrect": false}, {"id": "e14427bb-19c0-4df3-8001-02a805ed4d28", "text": "Ötszögek", "isCorrect": false}], "timeLimit": 15}, {"id": "3e2590ee-d217-45e3-809f-99888b20cf2e", "text": "A testek felülről, elölről és oldalról készített 2D vetületei a vetületi képek.", "type": "true-false", "options": [{"id": "7f10a6d9-98d6-40bb-9774-f83a60ee5b9c", "text": "Igaz", "isCorrect": true}, {"id": "c9bf0660-5b62-42c8-b052-0b10af19f9d2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9b4861a2-8c6f-4498-b2d0-0084ec7bd8ea", "text": "Hány lapja van a négyszög alapú gúlának (piramisnak)? (1 alap + 4 oldal)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}]'::jsonb, true, NOW()),
('10074f29-5da4-47a0-8ce5-67a7fe623d6c', '21feff02-016d-46e2-bb9d-c27495133b1b', '107. óra: Testek felszíne', 'Kocka és téglatest felszínének kiszámítása (A vagy F).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "20580493-0ba9-4323-80ce-5c420ec2e2e8", "text": "Mi a kocka felszínének képlete (''a'' éllel)?", "type": "multiple-choice", "options": [{"id": "4f7cca4a-f0c4-4820-ae02-50de57763a73", "text": "F = 6 * a * a (6 * a²)", "isCorrect": true}, {"id": "b09e4673-db82-4d67-aeac-9c208cec2c63", "text": "F = a * a * a", "isCorrect": false}, {"id": "36f63578-da20-4961-a538-564153af8684", "text": "F = 12 * a", "isCorrect": false}, {"id": "91514a68-ea8d-418c-afa1-9fc35edf55c7", "text": "F = 4 * a²", "isCorrect": false}], "timeLimit": 15}, {"id": "c3b4cdb5-eabe-452b-9412-db324290ed11", "text": "Mi a téglatest felszínének képlete (a, b, c élekkel)?", "type": "multiple-choice", "options": [{"id": "db036a61-ae52-4cb2-86c9-175222252474", "text": "F = 2 * (a*b + a*c + b*c)", "isCorrect": true}, {"id": "22b2af9e-8add-4d3b-969b-98dbff771277", "text": "F = a * b * c", "isCorrect": false}, {"id": "81e739b9-0c25-4e51-80a1-6d0e41a623f3", "text": "F = 4 * (a + b + c)", "isCorrect": false}, {"id": "fc7e0abd-1be5-4795-b640-0d5985593286", "text": "F = a*b + c", "isCorrect": false}], "timeLimit": 15}, {"id": "4353bcff-2818-4be9-8445-fd0ee00db59e", "text": "Mennyi a 3 cm élű kocka felszíne? (6 * 3 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "54"}, {"id": "7f435660-c326-4d26-a2a6-cb9c34b2ca36", "text": "Mennyi a 2 cm, 3 cm, 4 cm élű téglatest felszíne? (2*(2*3 + 2*4 + 3*4) = 2*(6+8+12) = 2*26)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "52"}, {"id": "4fdd2961-0feb-4d03-aa4d-0a4c47009306", "text": "A felszín a testet határoló lapok területeinek összege.", "type": "true-false", "options": [{"id": "8e5e48f8-b6e5-42dc-b491-55656af73a0e", "text": "Igaz", "isCorrect": true}, {"id": "e321f42f-7952-4ffe-86d8-d7650b942f95", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0176f90f-6dd4-4700-a46d-1b003bc8c409", "text": "A felszínt mindig terület-mértékegységben (cm², m²) adjuk meg.", "type": "true-false", "options": [{"id": "50db59de-f44d-4187-a586-3fb674ecbd77", "text": "Igaz", "isCorrect": true}, {"id": "971d9a08-1a85-4f84-9f80-a58e93c39e06", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "68bae3da-5fbb-4148-a3e6-e324943ea4bd", "text": "Mennyi a 10 cm élű kocka felszíne? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "600"}]'::jsonb, true, NOW()),
('16264b14-b6a8-4271-a818-7e933bcd2f3f', '21feff02-016d-46e2-bb9d-c27495133b1b', '108. óra: Gyakorlóóra', 'Felszínszámítás gyakorlása hálók megrajzolásával és szerkesztőprogrammal.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "8f0ab9e2-7264-4891-bf53-99a2fac26f7b", "text": "Hány négyzetből áll a kocka hálója?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "1d0db5a2-b5b1-41ed-86d7-4438effb4146", "text": "Mennyi a 4 cm élű kocka felszíne? (6 * 16)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "96"}, {"id": "84f4858c-a264-4d52-bfbe-c3e2786d29a4", "text": "Mennyi a 1 m, 2 m, 3 m élű téglatest felszíne? (2*(2+3+6) = 2*11)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "8a088d13-04c1-408d-941a-8469b2be61c1", "text": "A test hálójának területe megegyezik a test felszínével.", "type": "true-false", "options": [{"id": "09932d6f-4d76-4db1-b803-53d525bfcd08", "text": "Igaz", "isCorrect": true}, {"id": "1b189d16-e7a7-4c21-94d8-92df2902bf1c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d62ff361-788b-40d0-af19-89ce017bdd33", "text": "Mennyi a 5 cm élű kocka felszíne? (6 * 25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "18b25617-fb95-4c5a-99bd-d7cf892295b1", "text": "Dinamikus szerkesztőprogrammal a testek hálója kiteríthető és összehajtható.", "type": "true-false", "options": [{"id": "8b605906-9c58-4455-9ec0-48f6b36733b1", "text": "Igaz", "isCorrect": true}, {"id": "096f17b5-935f-4a0d-9241-f067ba6f4f5f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "498ce0a5-718b-43db-af4d-f4f5ff42ead2", "text": "A téglatest szemközti lapjai egyenlő területűek.", "type": "true-false", "options": [{"id": "ef695055-83c1-41ec-b9d0-ec640b258337", "text": "Igaz", "isCorrect": true}, {"id": "499c64ed-6fbc-4162-8054-fe26f41cbf48", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('80d7a96b-ce1f-475c-b022-c1e6834c0496', '21feff02-016d-46e2-bb9d-c27495133b1b', '109. óra: Felszínszámítással kapcsolatos gyakorlati feladatok', 'Dobozok lefestése, csomagolópapír szükséglet kiszámítása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "b7ae2396-0507-45d4-8454-7f539a85a8a7", "text": "Egy 10 cm x 20 cm x 30 cm-es téglatest dobozt befestünk. Hány cm² felületet kell lefesteni? (2*(200+300+600) = 2*1100)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2200"}, {"id": "d9e99374-0e0e-4778-bdd6-61c9a4aa5a30", "text": "Hány cm² csomagolópapír kell egy 5 cm élű kocka alakú ajándék becsomagolásához (ráhagyás nélkül)? (6 * 25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "8fe2a590-f117-4232-8827-aa36a51498d2", "text": "Ha a festékből 1 m²-re 200 g kell, hány gramm festék kell 5 m² felszínre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "b25f1768-a666-4fd7-afc4-01aa1742527a", "text": "Csomagoláskor a veszteség és az átfedés miatt érdemes a kiszámított felszínnél kb. 10-20%-kal több papírral számolni.", "type": "true-false", "options": [{"id": "a469bff6-c43c-4462-a4d8-b3b959bc9712", "text": "Igaz", "isCorrect": true}, {"id": "edb5b036-f1fb-4a54-b36c-40160b948c55", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "11f70060-1d3e-4ea1-9a73-77192f44c6b8", "text": "Mennyi a 2 cm élű kocka felszíne? (6 * 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "1bdde737-7d3c-4456-a5ea-cc383e0f9645", "text": "A dobozok tervezésénél az anyagszükségletet a felszín határozza meg.", "type": "true-false", "options": [{"id": "d5e04e1c-c369-41ba-9d37-527645a66c7d", "text": "Igaz", "isCorrect": true}, {"id": "02f4f92a-06b8-4f03-a657-ed455e113d65", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "11deb680-a280-4368-a3cb-56e91bc9bed3", "text": "Mennyi a 1 cm élű kocka felszíne?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}]'::jsonb, true, NOW()),
('1688e78a-baaf-4bb7-8a99-29fcd0abf2fe', '21feff02-016d-46e2-bb9d-c27495133b1b', '110. óra: Testek térfogata', 'Téglatest és kocka térfogatának (V) kiszámítása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "29b96f3b-948f-46b1-b2af-d81675fff8db", "text": "Mi a kocka térfogatának képlete (''a'' éllel)?", "type": "multiple-choice", "options": [{"id": "2248d16f-a865-495b-934c-4aa0d55093fd", "text": "V = a * a * a (a³)", "isCorrect": true}, {"id": "6a607fe3-70e5-4b13-a7d2-5013567d2ed9", "text": "V = 6 * a²", "isCorrect": false}, {"id": "052d11fb-b1e0-4280-835e-3a8ed6367897", "text": "V = 12 * a", "isCorrect": false}, {"id": "5dc4ce5b-218a-4fde-99b2-bafd7d8d81bb", "text": "V = a + a + a", "isCorrect": false}], "timeLimit": 15}, {"id": "006594b7-a6c1-491a-bc3e-7b2337689242", "text": "Mi a téglatest térfogatának képlete (a, b, c élekkel)?", "type": "multiple-choice", "options": [{"id": "1a5251e1-cc6b-4f81-b4ce-d0cc60123f14", "text": "V = a * b * c", "isCorrect": true}, {"id": "39bb924b-e76a-4c9a-991e-05b7f2ff41a7", "text": "V = 2 * (a+b+c)", "isCorrect": false}, {"id": "f8269281-4d42-4f2f-b34c-6caa86ee756d", "text": "V = a * b", "isCorrect": false}, {"id": "57183d16-b92e-4714-86b0-684741a6bdef", "text": "V = a + b + c", "isCorrect": false}], "timeLimit": 15}, {"id": "cb2aef17-4edd-4c89-9099-e817bf939d00", "text": "Mennyi a 3 cm élű kocka térfogata? (3 * 3 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "414a69a6-e76e-456e-ab21-d6d4fbe089b4", "text": "Mennyi a 2 cm, 4 cm, 5 cm élű téglatest térfogata? (2 * 4 * 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "2e75d39b-4cee-4810-a85f-ccb0de7e9df4", "text": "A térfogatot mindig köbmértékegységben (cm³, m³, dm³) vagy űrmértékben (liter, dl) adjuk meg.", "type": "true-false", "options": [{"id": "4f6cf4d5-8fbb-4b9d-95e5-15260bdfdbbe", "text": "Igaz", "isCorrect": true}, {"id": "c3fd04e5-60ec-4e6d-a2bb-b2d7f07f7725", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "221fabae-d467-4bd8-b0a3-4341a42efea2", "text": "Mennyi a 4 cm élű kocka térfogata? (4 * 4 * 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "6a68683c-b1a0-4692-8827-f090bfa85b7c", "text": "Mennyi a 10 cm élű kocka térfogata cm³-ben? (1000 cm³ = 1 liter)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW()),
