"A csoportszervezés és munkamegosztás felgyorsítja a projekt elvégzését.", "type": "true-false", "options": [{"id": "4a439b5e-45bf-4114-8e39-a5f714d280d7", "text": "Igaz", "isCorrect": true}, {"id": "b459178d-1205-4a8b-9f8a-b5222319a683", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "26376776-9aed-4d2b-8eb1-edd67fb43204", "text": "Hány oldallapja van a téglatest alakú épületnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]'::jsonb, true, NOW()),
